def slugify(text):
    lowered = text.lower()
    replaced = re.sub(r"[^a-z0-9\u4e00-\u9fff]+", "-", lowered).strip("-")
    return replaced[:80]


def obsidian_link(path):
    return f"[[{path.stem}]]"


def wiki_filename(title):
    return f"{title}.md"


def strip_frontmatter(text):
    if text.startswith("---"):
        parts = text.split("---", 2)
        if len(parts) == 3:
            return parts[2].strip()
    return text.strip()


def frontmatter_value(path, field):
    if not path.exists():
        return None
    text = path.read_text(encoding="utf-8")
    if not text.startswith("---"):
        return None
    parts = text.split("---", 2)
    if len(parts) != 3:
        return None
    match = re.search(rf"^{re.escape(field)}:\s*(.+)$", parts[1], re.MULTILINE)
    if not match:
        return None
    value = match.group(1).strip()
    if value.startswith('"') and value.endswith('"'):
        return value[1:-1]
    if value.startswith("'") and value.endswith("'"):
        return value[1:-1]
    return value


def first_heading_or_stem(path, text):
    for line in text.splitlines():
        if line.startswith("# "):
            return line[2:].strip()
    return path.stem


def plain_preview(text, max_chars=220):
    lines = []
    for line in text.splitlines():
        clean = line.strip()
        if clean.startswith("#"):
            clean = clean.lstrip("#").strip()
        if clean:
            lines.append(clean)
    merged = " ".join(lines)
    return merged[:max_chars]


def classify_note(path, text):
    haystack = f"{path.as_posix()} {path.stem} {text[:3000]}".lower()
    matched = []
    for rule in CATEGORY_RULES:
        score = 0
        for keyword in rule["keywords"]:
            if keyword.lower() in haystack:
                score += 1
        if score > 0:
            matched.append((score, rule))
    matched.sort(key=lambda item: (-item[0], item[1]["slug"]))
    if matched:
        return matched[0][1], [item[1] for item in matched]
    return {
        "slug": "uncategorized_notes",
        "title": "Uncategorized Notes",
        "kind": "concept",
        "keywords": [],
        "tags": ["uncategorized"],
    }, []


def source_type_for(path, text):
    haystack = f"{path.as_posix()} {path.stem} {text[:2000]}".lower()
    if "nature" in haystack or "science" in haystack or "cell" in haystack or "biorxiv" in haystack or "缁艰堪" in haystack or "璁烘枃" in haystack:
        return "article"
    if "鏁欑▼" in haystack or "宸ュ叿" in haystack or "浠ｇ爜" in haystack:
        return "notes"
    return "notes"


